using System;using System.Collections.Generic;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Security.Cryptography;using System.Threading;using System.Threading.Tasks;
namespace FoolLauncher {
 public sealed class LocalMod {
  public string File,Hash,Name,Version,Description,Id,Source,Project,RemoteVersion,Slug,CheckNote;public bool Disabled;public CatalogVersion Update;public string Checked;
  public string Title {get{return Name+"  ·  "+Version+(Disabled?"  [已禁用]":"");}}public string Detail {get{return (Update==null?"":"可更新 → "+Update.Number+"  ·  ")+(Description??"")+"  ·  "+File;}}
  [System.Web.Script.Serialization.ScriptIgnore]public System.Windows.Media.ImageSource Icon {get;set;}
 }
 public sealed class DisabledMod {public string File;public PackFile Entry;}
 public sealed class ModManager {
  readonly PackService Service;public readonly ModNameTranslations Names;readonly CatalogService Api=new CatalogService();public ModManager(PackService service){Service=service;Names=new ModNameTranslations(service.Data);}
  public static LocalMod Read(string path){var mod=new LocalMod{File=Path.GetFileName(path),Name=Path.GetFileName(path),Version="未知版本",Description="",Disabled=path.EndsWith(".disabled",StringComparison.OrdinalIgnoreCase)};using(var sha=SHA1.Create())using(var stream=File.OpenRead(path))mod.Hash=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();try{using(var zip=ZipFile.OpenRead(path)){if(zip.Entries.Count>40000)return mod;
   Func<string,string> read=name=>{var entry=zip.GetEntry(name);if(entry==null||entry.Length>2*1024*1024)return null;using(var r=new StreamReader(entry.Open()))return r.ReadToEnd();};string json=read("fabric.mod.json"),icon=null;Dictionary<string,object> data=null;
   if(json!=null)data=Json.Parse<Dictionary<string,object>>(json);else if((json=read("quilt.mod.json"))!=null){var outer=Json.Parse<Dictionary<string,object>>(json);object loader;if(outer.TryGetValue("quilt_loader",out loader))data=loader as Dictionary<string,object>;}
   if(data!=null){Func<string,string> value=k=>data.ContainsKey(k)?Convert.ToString(data[k]):null;mod.Id=value("id");mod.Name=value("name")??mod.Id??mod.Name;mod.Version=value("version")??mod.Version;mod.Description=value("description")??"";icon=value("icon");object meta;if(data.TryGetValue("metadata",out meta)&&meta is Dictionary<string,object>){var m=(Dictionary<string,object>)meta;if(m.ContainsKey("name"))mod.Name=Convert.ToString(m["name"]);if(m.ContainsKey("icon"))icon=Convert.ToString(m["icon"]);}}
   else {string toml=read("META-INF/mods.toml")??read("META-INF/neoforge.mods.toml");if(toml!=null){Func<string,string> value=k=>{var m=Regex.Match(toml,"(?m)^\\s*"+k+"\\s*=\\s*[\"']([^\"'\\r\\n]+)");return m.Success?m.Groups[1].Value:null;};mod.Id=value("modId");mod.Name=value("displayName")??mod.Id??mod.Name;mod.Version=value("version")??mod.Version;mod.Description=value("description")??"";icon=value("logoFile");if(mod.Version.Contains("${")){string manifest=read("META-INF/MANIFEST.MF")??"";var m=Regex.Match(manifest,@"(?m)^Implementation-Version:\s*(.+)");mod.Version=m.Success?m.Groups[1].Value.Trim():"未知版本";}}
    else if((json=read("mcmod.info"))!=null){var m=Regex.Match(json,"\"name\"\\s*:\\s*\"([^\"]+)");if(m.Success)mod.Name=m.Groups[1].Value; m=Regex.Match(json,"\"version\"\\s*:\\s*\"([^\"]+)");if(m.Success)mod.Version=m.Groups[1].Value;}}
   if(icon!=null){var e=zip.GetEntry(icon.Replace('\\','/'));if(e!=null&&e.Length<1024*1024)using(var input=e.Open())using(var memory=new MemoryStream()){input.CopyTo(memory);mod.Icon=UiPreferences.Decode(memory.ToArray());}}
  }}catch{mod.Description="部分元数据无法读取";}return mod;}
  public LocalMod[] List(Instance instance,CancellationToken ct){string folder=Service.Folder(instance),mods=Path.Combine(Service.Game(instance),"mods");LauncherUpdateCore.NoLinks(mods);Directory.CreateDirectory(mods);var cacheFile=Path.Combine(folder,"mod-manager-cache.json");var cache=new List<LocalMod>();try{cache=Json.Read<List<LocalMod>>(cacheFile);}catch{}var receipts=new List<InstalledCatalogMod>();try{receipts=Json.Read<List<InstalledCatalogMod>>(Path.Combine(folder,"catalog-mods.json"));}catch{}var list=new List<LocalMod>();foreach(string file in Directory.GetFiles(mods).Where(p=>p.EndsWith(".jar",StringComparison.OrdinalIgnoreCase)||p.EndsWith(".jar.disabled",StringComparison.OrdinalIgnoreCase))){ct.ThrowIfCancellationRequested();LauncherUpdateCore.NoLinks(file);var row=Read(file);var old=cache.FirstOrDefault(c=>c.Hash==row.Hash);if(old!=null){row.Source=old.Source;row.Project=old.Project;row.RemoteVersion=old.RemoteVersion;row.Slug=old.Slug;row.Update=old.Update;row.Checked=old.Checked;row.CheckNote=old.CheckNote;row.Name=Names.Lookup(row.Source,row.Slug)??row.Name;}if(row.Project==null){var receipt=receipts.FirstOrDefault(r=>r.FileName==row.File);if(receipt!=null){row.Source=receipt.Source;row.Project=receipt.Project;row.RemoteVersion=receipt.Version;}}list.Add(row);}return list.OrderBy(m=>m.Disabled).ThenBy(m=>m.Name,StringComparer.CurrentCultureIgnoreCase).ToArray();}
  public async Task Check(Instance instance,LocalMod[] rows,IProgress<Update> progress,CancellationToken ct,bool force){var target=ModTarget.Capture(Service,instance);await Names.EnsureAsync();var cache=new Dictionary<string,CurseFile>();string cf=Path.Combine(Service.Data,"metadata","curseforge");if(Directory.Exists(cf))foreach(string file in Directory.GetFiles(cf,"*.json"))try{var f=Json.Read<CurseFileResponse>(file).data;if(f!=null)foreach(var h in f.hashes??new CurseHash[0])if(h.algo==1)cache[h.value.ToLowerInvariant()]=f;}catch{}
   int done=0;using(var gate=new SemaphoreSlim(4))await Task.WhenAll(rows.Select(async row=>{await gate.WaitAsync(ct);try{DateTime checkedAt;if(!force&&DateTime.TryParse(row.Checked,out checkedAt)&&checkedAt.ToUniversalTime()>DateTime.UtcNow.AddHours(-6))return;row.Update=null;
    CatalogVersion current=null;CurseFile cached;if(cache.TryGetValue(row.Hash,out cached)){row.Source="curseforge";row.Project=cached.modId.ToString();row.RemoteVersion=cached.id.ToString();}
    if(row.Project==null){var raw=Json.Parse<Dictionary<string,object>>(await CatalogNetwork.Json("https://api.modrinth.com/v2/version_file/"+row.Hash+"?algorithm=sha1",ct));row.Source="modrinth";row.Project=CatalogService.Id(Convert.ToString(raw["project_id"]));row.RemoteVersion=CatalogService.Id(Convert.ToString(raw["id"]));}
    current=await Api.Version(row.Source,row.Project,row.RemoteVersion,ct);if(!PackService.Verify(PackService.SafePath(Path.Combine(target.Folder,"minecraft","mods"),row.File),new PackFile{fileSize=current.File.Size,hashes=current.File.Hashes}))throw new IOException("文件与资源站记录不一致");
    string url=row.Source=="modrinth"?"https://api.modrinth.com/v2/project/"+row.Project:"";var project=Json.Parse<Dictionary<string,object>>(row.Source=="modrinth"?await CatalogNetwork.Json(url,ct):await CatalogNetwork.Curse("mods/"+row.Project,ct));if(row.Source=="curseforge")project=(Dictionary<string,object>)project["data"];row.Slug=Convert.ToString(project["slug"]);row.Name=Names.Lookup(row.Source,row.Slug)??row.Name;
    var candidates=await Api.Versions(new CatalogProject{Id=row.Project,Source=row.Source,Kind="mod"},target.Game,target.Loader,0,ct);DateTime published;DateTime.TryParse(current.Published,out published);row.Update=candidates.FirstOrDefault(v=>v.Channel=="release"&&v.Id!=current.Id&&String.CompareOrdinal(v.Published,current.Published)>0&&v.File!=null&&!v.File.Hashes.Values.Any(h=>String.Equals(h,row.Hash,StringComparison.OrdinalIgnoreCase)));row.CheckNote=row.Update==null?"未发现兼容的新正式版":"有兼容的新版本";row.Checked=DateTime.UtcNow.ToString("o");
   }catch(OperationCanceledException){throw;}catch(Exception ex){row.CheckNote="未识别或检查失败："+ex.Message;}finally{progress.Report(new Update("检查模组更新 "+Interlocked.Increment(ref done)+" / "+rows.Length,done,rows.Length));gate.Release();}}));ct.ThrowIfCancellationRequested();target.Check(Service);Json.Write(Path.Combine(target.Folder,"mod-manager-cache.json"),rows);
  }
  public void Change(Instance instance,LocalMod row,bool delete,CancellationToken ct){string folder=Service.Folder(instance),mods=Path.Combine(Service.Game(instance),"mods"),path=PackService.SafePath(mods,row.File);LauncherUpdateCore.NoLinks(path);if(!File.Exists(path)||Read(path).Hash!=row.Hash)throw new IOException("模组文件已变化，请刷新。");var index=Service.Index(instance);var entries=index.files.ToList();string relative="mods/"+row.File;var original=entries.FirstOrDefault(f=>f.path.Equals(relative,StringComparison.OrdinalIgnoreCase));entries.RemoveAll(f=>f.path.Equals(relative,StringComparison.OrdinalIgnoreCase));string stateFile=Path.Combine(folder,"disabled-mods.json");var state=File.Exists(stateFile)?Json.Read<List<DisabledMod>>(stateFile):new List<DisabledMod>();var saved=state.FirstOrDefault(s=>s.File==row.File);state.RemoveAll(s=>s.File==row.File);
   string stage=Path.Combine(folder,".mod-change-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);try{var writes=new List<KeyValuePair<string,string>>{new KeyValuePair<string,string>(path,null)};if(!delete){string name=row.Disabled?row.File.Substring(0,row.File.Length-9):row.File+".disabled",dest=PackService.SafePath(mods,name);if(File.Exists(dest))throw new IOException("目标文件已存在。");string copy=Path.Combine(stage,"mod.jar");File.Copy(path,copy);writes.Add(new KeyValuePair<string,string>(dest,copy));if(row.Disabled){if(saved!=null&&saved.Entry!=null){saved.Entry.path="mods/"+name;entries.Add(saved.Entry);}}else state.Add(new DisabledMod{File=name,Entry=original});}
    index.files=entries.ToArray();string i=Path.Combine(stage,"index.json"),s=Path.Combine(stage,"state.json");Json.Write(i,index);Json.Write(s,state);writes.Add(new KeyValuePair<string,string>(Path.Combine(folder,"pack-index.json"),i));writes.Add(new KeyValuePair<string,string>(stateFile,s));CatalogInstaller.Commit(folder,stage,Path.Combine(folder,"mod-backups",DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6)),writes,ct,null);
   }finally{if(Directory.Exists(stage))Directory.Delete(stage,true);}}
 }
}
